package com.wds.sixstarsstandalone;

import org.json.JSONArray;
import org.json.JSONObject;

import java.time.OffsetDateTime;
import java.util.*;

/**
 * Android port of the server's profile-driven emotion-vector relationship scoring: the model supplies
 * evidence, while profile emotionInfluence + relationshipStats accumulators award H/T/R deterministically.
 */
final class DeterministicRelationshipEngine {
    private final StandaloneSettings settings;
    DeterministicRelationshipEngine(StandaloneSettings settings) { this.settings = settings; }
    static final class Result {
        final JSONObject delta = new JSONObject();
        final JSONArray positiveSignals = new JSONArray();
        final JSONArray negativeSignals = new JSONArray();
        final JSONArray combos = new JSONArray();
        final JSONArray topEmotions = new JSONArray();
        String summary = "";
    }

    Result calculate(JSONObject profile, JSONObject state, JSONObject review, String playerText) throws Exception {
        Result r = new Result(); r.delta.put("Heart",0).put("Trust",0).put("Romance",0).put("BenaveilInfluence",0).put("EmotionalConnectionPercent",0.0);
        List<Signal> pos=parseVector(review.optString("emotionalEffectVector",""),AndroidPromptBuilder.POSITIVE_EMOTIONS);
        List<Signal> neg=parseVector(review.optString("negativeEmotionVector",""),AndroidPromptBuilder.NEGATIVE_EMOTIONS);
        Map<String,JSONObject> influence=influence(profile);
        JSONObject history=new JSONObject().put("CreatedAt",OffsetDateTime.now().toString()).put("TurnId",System.currentTimeMillis()+"_"+profile.optString("starId","")).put("RequestType","Chat").put("PlayerText",truncate(playerText,500));
        JSONArray entries=new JSONArray();history.put("Entries",entries);
        boolean romanceGate=isRomanceGateOpen(profile,state,pos,playerText);

        for(Signal s:pos) if(s.hasAny()){ JSONObject item=historyItem(s,influence.get(s.id.toLowerCase(Locale.ROOT)),"positive",false); entries.put(item); if(item.optBoolean("Accepted")){r.positiveSignals.put(formatSignal(item));applyStatScores(profile,state,item,r.delta,true,romanceGate);} addTop(r,s,"positive",item.optBoolean("Accepted")); }
        for(Signal s:neg) if(s.hasAny()){ JSONObject item=historyItem(s,influence.get(s.id.toLowerCase(Locale.ROOT)),"negative",true); entries.put(item); if(item.optBoolean("Accepted")){r.negativeSignals.put(formatSignal(item));applyStatScores(profile,state,item,r.delta,true,romanceGate); } addTop(r,s,"negative",item.optBoolean("Accepted")); }

        List<String> combos=detectCombos(profile,state,history,review.optJSONArray("detectedCombos"));
        for(String combo:combos){r.combos.put(combo);applyCombo(profile,state,history,combo,r.delta,romanceGate);}
        applyMajorNegative(r.delta,neg,settings.romanceMode());
        applySuggestedNonHtr(r.delta,review.optJSONObject("suggestedStateDeltas"),pos,neg,combos);
        applyConnection(profile,state,r.delta,pos,neg,combos,playerText);
        clamp(profile,r.delta);

        double before=state.optDouble("EmotionalConnectionPercent",0);
        double after=clampDouble(before+r.delta.optDouble("EmotionalConnectionPercent",0),0,100);
        r.summary="Deterministic emotion update: skill=star_specific_vector_scoring; met="+state.optBoolean("IsMet",false)+"; ally="+state.optBoolean("IsAlly",false)+"; connection="+fmt(before)+"%->"+fmt(after)+"%; positiveSignals="+r.positiveSignals.length()+"; negativeSignals="+r.negativeSignals.length()+"; acceptedCombos="+join(r.combos)+"; accumulators="+accumulatorSummary(state)+"; romanceGate="+romanceGate+"; actualDelta=(H"+r.delta.optInt("Heart")+",T"+r.delta.optInt("Trust")+",R"+r.delta.optInt("Romance")+",B"+r.delta.optInt("BenaveilInfluence")+",C"+String.format(Locale.US,"%.2f",r.delta.optDouble("EmotionalConnectionPercent"))+ ").";
        history.put("ComboHits",r.combos);history.put("Summary",r.summary);
        if(entries.length()>0){JSONArray vh=state.optJSONArray("EmotionVectorHistory");if(vh==null){vh=new JSONArray();state.put("EmotionVectorHistory",vh);}prepend(vh,history,256);}
        sortTop(r.topEmotions);
        return r;
    }


    private static JSONObject historyItem(Signal s,JSONObject rule,String fallback,boolean boundary)throws Exception{
        if(rule==null)rule=new JSONObject().put("emotion",s.id).put("polarity",fallback).put("affectsStar",0.10).put("statWeights",new JSONObject());
        double affects=clampDouble(rule.optDouble("affectsStar",0),0,1);double starScore=s.weighted()*affects;JSONObject weights=rule.optJSONObject("statWeights");if(weights==null)weights=new JSONObject();
        double heart=starScore*weights.optDouble("heart",0),trust=starScore*weights.optDouble("trust",0),romance=starScore*weights.optDouble("romance",0);String polarity=rule.optString("polarity",fallback);
        boolean hasEffect=Math.abs(heart)+Math.abs(trust)+Math.abs(romance)>=.001;boolean accepted=boundary?(s.hasAny()&&(s.weighted()>=8||(s.confidence>=.35&&s.score>=35))&&affects>0&&hasEffect):(s.hasAny()&&affects>0&&hasEffect);
        return new JSONObject().put("Emotion",s.id).put("Polarity",polarity).put("Confidence",s.confidence).put("Score",s.score).put("WeightedScore",s.weighted()).put("AffectsStar",affects).put("Accepted",accepted).put("HeartScore",heart).put("TrustScore",trust).put("RomanceScore",romance).put("Reason",s.id+" affects this Star "+fmt(affects)+" with H/T/R score "+fmt(heart)+"/"+fmt(trust)+"/"+fmt(romance));
    }

    private static void applyStatScores(JSONObject profile,JSONObject state,JSONObject item,JSONObject delta,boolean allowPositive,boolean romanceGate)throws Exception{
        applyOne(profile,state,"heart",item.optDouble("HeartScore",0),delta,true);
        applyOne(profile,state,"trust",item.optDouble("TrustScore",0),delta,true);
        double rs=item.optDouble("RomanceScore",0);if(romanceGate||rs<0)applyOne(profile,state,"romance",rs,delta,true);
    }

    private static void applyOne(JSONObject profile,JSONObject state,String stat,double score,JSONObject delta,boolean allowCashout)throws Exception{
        if(Math.abs(score)<.01)return;JSONObject rules=profile.optJSONObject("relationshipStats");JSONObject rule=rules==null?null:rules.optJSONObject(stat);double scorePer=rule==null?(stat.equals("romance")?120:stat.equals("trust")?90:80):rule.optDouble("scorePerPoint",80);int max=rule==null?(stat.equals("romance")?1:2):Math.max(1,rule.optInt("maxPerTurn",2));
        JSONObject accumulator=getAccumulator(state,stat);double total=accumulator.optDouble("Score",0)+score;accumulator.put("Score",total).put("LastScoreAdded",score).put("LastUpdatedAt",OffsetDateTime.now().toString());if(!allowCashout&&total>0)return;double threshold=Math.max(1,scorePer);if(total>0)threshold=Math.max(8,threshold*.35);int points=0;if(total>=threshold){points=Math.min(max,(int)Math.floor(total/threshold));total-=points*threshold;accumulator.put("TotalPositivePoints",accumulator.optInt("TotalPositivePoints",0)+points);}else if(total<=-threshold){points=-Math.min(max,(int)Math.floor(Math.abs(total)/threshold));total-=points*threshold;accumulator.put("TotalNegativePoints",accumulator.optInt("TotalNegativePoints",0)-points);}accumulator.put("Score",total);if(points!=0){String key=stat.equals("heart")?"Heart":stat.equals("trust")?"Trust":"Romance";delta.put(key,delta.optInt(key,0)+points);}
    }

    private static JSONObject getAccumulator(JSONObject state,String stat)throws Exception{JSONArray a=state.optJSONArray("RelationshipScoreAccumulators");if(a==null){a=new JSONArray();state.put("RelationshipScoreAccumulators",a);}for(int i=0;i<a.length();i++){JSONObject x=a.optJSONObject(i);if(x!=null&&x.optString("Stat").equalsIgnoreCase(stat))return x;}JSONObject x=new JSONObject().put("Stat",stat).put("Score",0.0).put("TotalPositivePoints",0).put("TotalNegativePoints",0);a.put(x);return x;}

    private static List<String> detectCombos(JSONObject profile,JSONObject state,JSONObject current,JSONArray model)throws Exception{
        LinkedHashSet<String> result=new LinkedHashSet<>();JSONArray rules=profile.optJSONArray("comboRules");if(rules!=null)for(int i=0;i<rules.length()&&result.size()<4;i++){JSONObject rule=rules.optJSONObject(i);if(rule!=null&&comboMatches(rule,state,current))result.add(slug(rule.optString("comboId","")));}
        if(model!=null)for(int i=0;i<model.length()&&result.size()<4;i++){String id=slug(model.optString(i));if(id.isEmpty())continue;if(profileHasCombo(profile,id)||isLegacyCombo(id))result.add(id);}
        return new ArrayList<>(result);
    }

    private static boolean comboMatches(JSONObject rule,JSONObject state,JSONObject current){int turns=Math.max(1,rule.optInt("withinTurns",4));List<JSONObject> history=new ArrayList<>();history.add(current);JSONArray old=state.optJSONArray("EmotionVectorHistory");if(old!=null)for(int i=0;i<Math.min(turns-1,old.length());i++){JSONObject x=old.optJSONObject(i);if(x!=null)history.add(x);}JSONArray reqs=rule.optJSONArray("requires");if(reqs==null||reqs.length()==0)return false;Set<String> matched=new HashSet<>();for(int i=0;i<reqs.length();i++){JSONObject req=reqs.optJSONObject(i);if(req==null)continue;String emotion=req.optString("emotion","");boolean hit=false;for(JSONObject h:history){JSONArray es=h.optJSONArray("Entries");if(es==null)continue;for(int j=0;j<es.length();j++){JSONObject item=es.optJSONObject(j);if(item==null||!item.optBoolean("Accepted"))continue;if(!item.optString("Emotion").equalsIgnoreCase(emotion))continue;double minC=req.optDouble("minConfidence",.01);minC=minC<=0?.01:Math.min(minC,.10);double minS=req.optDouble("minScore",1);minS=minS<=0?1:Math.max(8,minS*.35);double minW=Math.max(1,(req.optDouble("minScore",25))*0.025);if(item.optDouble("Confidence")>=minC&&item.optDouble("Score")>=minS&&item.optDouble("WeightedScore")>=minW){hit=true;break;}}if(hit)break;}if(hit)matched.add(emotion.toLowerCase(Locale.ROOT));else return false;}return matched.size()>=Math.max(1,rule.optInt("minimumDistinctEmotions",reqs.length()));}

    private static void applyCombo(JSONObject profile,JSONObject state,JSONObject current,String combo,JSONObject delta,boolean romanceGate)throws Exception{JSONObject rule=findCombo(profile,combo);if(rule==null){applyLegacy(profile,state,combo,delta,romanceGate);return;}double base=comboBase(rule,state,current);double bonus=base*(rule.optDouble("bonusMultiplier",1)<=0?1:rule.optDouble("bonusMultiplier",1));JSONObject w=rule.optJSONObject("statWeights");if(w==null)w=new JSONObject();applyOne(profile,state,"heart",bonus*w.optDouble("heart",0),delta,true);applyOne(profile,state,"trust",bonus*w.optDouble("trust",0),delta,true);if(romanceGate||isNegativeCombo(combo))applyOne(profile,state,"romance",bonus*w.optDouble("romance",0),delta,true);}
    private static double comboBase(JSONObject rule,JSONObject state,JSONObject current){JSONArray reqs=rule.optJSONArray("requires");if(reqs==null)return 45;List<Double>s=new ArrayList<>();List<JSONObject>hist=new ArrayList<>();hist.add(current);JSONArray old=state.optJSONArray("EmotionVectorHistory");if(old!=null)for(int i=0;i<Math.min(rule.optInt("withinTurns",4)-1,old.length());i++){JSONObject x=old.optJSONObject(i);if(x!=null)hist.add(x);}for(int i=0;i<reqs.length();i++){String e=reqs.optJSONObject(i)==null?"":reqs.optJSONObject(i).optString("emotion","");for(JSONObject h:hist){JSONArray es=h.optJSONArray("Entries");if(es==null)continue;for(int j=0;j<es.length();j++){JSONObject x=es.optJSONObject(j);if(x!=null&&x.optBoolean("Accepted")&&x.optString("Emotion").equalsIgnoreCase(e)){s.add(x.optDouble("WeightedScore",0)*Math.max(.05,x.optDouble("AffectsStar",0)));break;}}}}if(s.isEmpty())return 45;double sum=0;for(double x:s)sum+=x;return Math.max(35,sum/s.size());}

    private static void applyLegacy(JSONObject profile,JSONObject state,String c,JSONObject d,boolean gate)throws Exception{switch(c){case"trust_respect_combo":applyOne(profile,state,"heart",55,d,true);applyOne(profile,state,"trust",70,d,true);break;case"affection_plus_hope":case"private_vulnerability_safety":applyOne(profile,state,"heart",70,d,true);if(gate)applyOne(profile,state,"romance",40,d,true);d.put("BenaveilInfluence",d.optInt("BenaveilInfluence")-1);break;case"romantic_spark":if(gate)applyOne(profile,state,"romance",75,d,true);applyOne(profile,state,"heart",45,d,true);break;case"cruel_escalation":case"repeated_boundary_pressure":d.put("Heart",d.optInt("Heart")-2).put("Trust",d.optInt("Trust")-2).put("Romance",d.optInt("Romance")-1).put("BenaveilInfluence",d.optInt("BenaveilInfluence")+2);break;case"wounded_guard":d.put("Heart",d.optInt("Heart")-1).put("Trust",d.optInt("Trust")-1).put("BenaveilInfluence",d.optInt("BenaveilInfluence")+1);}}

    private static void applyMajorNegative(JSONObject d,List<Signal> neg,boolean romance)throws Exception{for(Signal s:neg){if(!(s.hasAny()&&(s.weighted()>=8||(s.confidence>=.35&&s.score>=35))))continue;switch(s.id){case"Disrespected":case"Pressured":case"CreepedOut":case"Unsafe":d.put("Trust",d.optInt("Trust")-1).put("Heart",d.optInt("Heart")-1);if(romance)d.put("Romance",d.optInt("Romance")-1);break;case"Hurt":d.put("Heart",d.optInt("Heart")-1).put("Trust",d.optInt("Trust")-1);if(romance&&s.score>=90)d.put("Romance",d.optInt("Romance")-1);break;case"Irritated":if(s.score>=90)d.put("Heart",d.optInt("Heart")-1);break;case"Bored":if(s.score>=92)d.put("Heart",d.optInt("Heart")-1);break;}if(s.id.equals("CreepedOut")||s.id.equals("Unsafe")||s.id.equals("Hurt"))d.put("BenaveilInfluence",d.optInt("BenaveilInfluence")+1);}}

    private static void applySuggestedNonHtr(JSONObject d,JSONObject s,List<Signal> pos,List<Signal> neg,List<String> combos)throws Exception{if(s==null)return;boolean positive=!pos.isEmpty();boolean negative=!neg.isEmpty();for(String c:combos){if(isNegativeCombo(c))negative=true;else positive=true;}int b=s.optInt("benaveilInfluence",s.optInt("BenaveilInfluence",0));double c=s.optDouble("emotionalConnectionPercent",s.optDouble("EmotionalConnectionPercent",0));if(positive)d.put("BenaveilInfluence",d.optInt("BenaveilInfluence")+Math.max(-1,Math.min(0,b)));if(negative)d.put("BenaveilInfluence",d.optInt("BenaveilInfluence")+Math.max(0,Math.min(1,b)));if(positive&&c>0)d.put("EmotionalConnectionPercent",d.optDouble("EmotionalConnectionPercent")+Math.min(.20,c));if((negative||pos.isEmpty())&&c<0)d.put("EmotionalConnectionPercent",d.optDouble("EmotionalConnectionPercent")+Math.max(-.60,c));}

    private static void applyConnection(JSONObject profile,JSONObject state,JSONObject d,List<Signal> pos,List<Signal> neg,List<String> combos,String text)throws Exception{double con=state.optDouble("EmotionalConnectionPercent",0);boolean ally=state.optBoolean("IsAlly",false)||profile.optString("starId").equalsIgnoreCase("Elusiaa");boolean major=neg.stream().anyMatch(x->x.score>=70&&x.confidence>=.60&&Arrays.asList("Disrespected","Pressured","CreepedOut","Hurt","Unsafe").contains(x.id));boolean bored=neg.stream().anyMatch(x->x.score>=75&&x.confidence>=.60&&(x.id.equals("Bored")||x.id.equals("Irritated")));if(major){d.put("EmotionalConnectionPercent",d.optDouble("EmotionalConnectionPercent")-1.25-Math.min(1.25,neg.size()*.45));return;}if(bored){d.put("EmotionalConnectionPercent",d.optDouble("EmotionalConnectionPercent")-.50);return;}boolean intimate=pos.stream().anyMatch(x->isIntimate(x.id)&&x.score>=10);long intimateCount=pos.stream().filter(x->isIntimate(x.id)&&x.score>=10).count();boolean personality=pos.stream().anyMatch(x->personalityMatch(profile.optString("starId"),x.id)&&x.score>=10);boolean combo=combos.stream().anyMatch(x->x.contains("romantic")||x.contains("affection")||x.contains("vulnerability")||x.contains("trust")||x.contains("tender")||x.contains("safe"));boolean effort=highEffort(text);if(ally&&intimate&&personality&&(intimateCount>=2||combo||effort||state.optInt("Romance")>=8||state.optInt("Trust")>=10)){double g=.75;if(intimateCount>=2)g+=.40;if(combo)g+=.35;if(effort)g+=.35;if(pos.stream().anyMatch(x->x.id.equals("Attracted")||x.id.equals("Yearning")))g+=.25;if(state.optInt("PositiveSuccessionCount")>=2||state.optInt("RomanticSuccessionCount")>=1)g+=.25;d.put("EmotionalConnectionPercent",d.optDouble("EmotionalConnectionPercent")+Math.min(2.25,g));return;}boolean any=pos.stream().anyMatch(Signal::hasAny);long high=pos.stream().filter(x->x.weighted()>=12||(x.score>=55&&x.confidence>=.20)).count();if(ally&&high>0){d.put("EmotionalConnectionPercent",d.optDouble("EmotionalConnectionPercent")+(high>=2?.55:.35));return;}if(ally&&any){d.put("EmotionalConnectionPercent",d.optDouble("EmotionalConnectionPercent")+.22);return;}if(ally&&text!=null&&!text.trim().isEmpty()&&neg.isEmpty()){d.put("EmotionalConnectionPercent",d.optDouble("EmotionalConnectionPercent")+.05);return;}if(con>0&&con<=50)d.put("EmotionalConnectionPercent",d.optDouble("EmotionalConnectionPercent")-.10);}

    private static boolean isRomanceGateOpen(JSONObject p,JSONObject s,List<Signal>pos,String text){if(!s.optBoolean("IsAlly",false)&&!p.optString("starId").equalsIgnoreCase("Elusiaa"))return false;boolean emotion=pos.stream().anyMatch(x->Arrays.asList("Flattered","Attracted","Tender","Yearning","Jealous","Affectionate").contains(x.id)&&x.score>=10);String t=text==null?"":text.toLowerCase(Locale.ROOT);boolean words=containsAny(t,"girlfriend","date","poem","poetry","beautiful","beauty","attracted","gentle","safe","trust","song","music","kiss","touch","fur","warm","miracle","stars","heart","light","eyes","precious","protect","sanctuary","cherish","faithful","falling for","drawn to you");boolean established=s.optBoolean("IsGirlfriend")||s.optInt("Romance")>0||s.optInt("Trust")>=4||s.optInt("Heart")>=4||s.optInt("PositiveSuccessionCount")>=2||s.optDouble("EmotionalConnectionPercent")>=8;return emotion||words||established;}

    private static void clamp(JSONObject p,JSONObject d)throws Exception{JSONObject stats=p.optJSONObject("relationshipStats");int hc=Math.max(2,stats!=null&&stats.optJSONObject("heart")!=null?stats.optJSONObject("heart").optInt("maxPerTurn",2):2),tc=Math.max(2,stats!=null&&stats.optJSONObject("trust")!=null?stats.optJSONObject("trust").optInt("maxPerTurn",2):2),rc=Math.max(1,stats!=null&&stats.optJSONObject("romance")!=null?stats.optJSONObject("romance").optInt("maxPerTurn",1):1);d.put("Heart",Math.max(-4,Math.min(hc,d.optInt("Heart"))));d.put("Trust",Math.max(-4,Math.min(tc,d.optInt("Trust"))));d.put("Romance",Math.max(-3,Math.min(rc,d.optInt("Romance"))));d.put("BenaveilInfluence",Math.max(-3,Math.min(3,d.optInt("BenaveilInfluence"))));d.put("EmotionalConnectionPercent",clampDouble(d.optDouble("EmotionalConnectionPercent"),-3,3));}

    private static Map<String,JSONObject> influence(JSONObject p){Map<String,JSONObject>m=new HashMap<>();JSONArray a=p.optJSONArray("emotionInfluence");if(a!=null)for(int i=0;i<a.length();i++){JSONObject x=a.optJSONObject(i);if(x!=null)m.put(x.optString("emotion","").toLowerCase(Locale.ROOT),x);}return m;}

    private static List<Signal> parseVector(String vector,String[] ids){List<Signal>r=new ArrayList<>();String[]parts=(vector==null?"":vector).split(";");for(int i=0;i<ids.length;i++){double c=0,s=0;if(i<parts.length){String[]x=parts[i].trim().split(":");try{if(x.length>0)c=Double.parseDouble(x[0]);}catch(Exception ignored){}try{if(x.length>1)s=Double.parseDouble(x[1]);}catch(Exception ignored){}}r.add(new Signal(ids[i],clampDouble(c,0,1),clampDouble(s,0,100)));}return r;}
    private static void addTop(Result r,Signal s,String val,boolean accepted)throws Exception{if(!s.hasAny())return;r.topEmotions.put(new JSONObject().put("EmotionId",s.id).put("Valence",val).put("Confidence",s.confidence).put("Score",s.score).put("WeightedScore",s.weighted()).put("AcceptedForStateUpdate",accepted));}
    private static void sortTop(JSONArray a)throws Exception{List<JSONObject>l=new ArrayList<>();for(int i=0;i<a.length();i++){JSONObject x=a.optJSONObject(i);if(x!=null)l.add(x);}l.sort((x,y)->Double.compare(y.optDouble("WeightedScore"),x.optDouble("WeightedScore")));while(a.length()>0)a.remove(a.length()-1);for(int i=0;i<Math.min(3,l.size());i++)a.put(l.get(i));}
    private static String formatSignal(JSONObject i){return i.optString("Emotion")+"("+String.format(Locale.US,"%.2f",i.optDouble("Confidence"))+":"+String.format(Locale.US,"%.0f",i.optDouble("Score"))+",star="+fmt(i.optDouble("AffectsStar"))+",H/T/R="+fmt(i.optDouble("HeartScore"))+"/"+fmt(i.optDouble("TrustScore"))+"/"+fmt(i.optDouble("RomanceScore"))+")";}
    private static JSONObject findCombo(JSONObject p,String id){JSONArray a=p.optJSONArray("comboRules");if(a!=null)for(int i=0;i<a.length();i++){JSONObject x=a.optJSONObject(i);if(x!=null&&slug(x.optString("comboId")).equals(id))return x;}return null;}
    private static boolean profileHasCombo(JSONObject p,String id){return findCombo(p,id)!=null;}
    private static boolean isLegacyCombo(String id){return Arrays.asList("trust_respect_combo","affection_plus_hope","private_vulnerability_safety","romantic_spark","cruel_escalation","repeated_boundary_pressure","wounded_guard").contains(id);}
    private static boolean isNegativeCombo(String c){String x=slug(c);return x.contains("hurt")||x.contains("wounded")||x.contains("cruel")||x.contains("pressure")||x.contains("guard")||x.contains("warning")||x.contains("unsafe")||x.contains("possessive");}
    private static boolean isIntimate(String id){return Arrays.asList("Affectionate","Vulnerable","Trusting","Safe","Protected","Tender","Flattered","Attracted","Yearning","Hopeful").contains(id);}
    private static boolean personalityMatch(String star,String id){switch(star.toLowerCase(Locale.ROOT)){case"elusiaa":return Arrays.asList("Comforted","Safe","Protected","Trusting","Tender","Hopeful","Wondrous","Affectionate","Sad","Concerned").contains(id);case"kaelia":return Arrays.asList("Intrigued","Wondrous","Hopeful","Respected","Trusting","Tender","Flattered","Attracted","Yearning","Vulnerable").contains(id);case"khavia":return Arrays.asList("Happy","Playful","Comforted","Safe","Trusting","Affectionate","Tender","Respected").contains(id);case"auerlis":return Arrays.asList("Happy","Amused","Playful","Hopeful","Admiring","Affectionate","Impassioned","Determined").contains(id);case"maera":return Arrays.asList("Protected","Trusting","Respected","Tender","Attracted","Yearning","Vulnerable","Safe").contains(id);case"nyxari":return Arrays.asList("Safe","Trusting","Vulnerable","Comforted","Tender","Hopeful","Intrigued","Respected").contains(id);default:return isIntimate(id);}}
    private static boolean highEffort(String text){String t=text==null?"":text.toLowerCase(Locale.ROOT);int letters=0;for(char c:t.toCharArray())if(Character.isLetter(c))letters++;if(containsAny(t,"poem","poetry","your eyes","your heart","miracle","beautiful","beauty","stars","sea","storm","safe","trust","i choose","i won't leave","i will stay","stand beside","precious","sanctuary","guard","protect","cherish","faithful","cat hair","fur","purr"))return true;return letters>=70&&containsAny(t,"you","your")&&containsAny(t,"heart","light","dark","safe","trust","beautiful","gentle","hope","mercy","truth","heal");}
    private static boolean containsAny(String t,String...n){for(String x:n)if(t.contains(x))return true;return false;}
    private static String slug(String v){String s=(v==null?"":v).trim().toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9]+","_").replaceAll("^_+|_+$","");return s;}
    private static String accumulatorSummary(JSONObject s){JSONArray a=s.optJSONArray("RelationshipScoreAccumulators");if(a==null||a.length()==0)return"none";StringBuilder b=new StringBuilder();for(int i=0;i<a.length();i++){JSONObject x=a.optJSONObject(i);if(x==null)continue;if(b.length()>0)b.append(", ");b.append(x.optString("Stat")).append('=').append(fmt(x.optDouble("Score")));}return b.toString();}
    private static void prepend(JSONArray a,JSONObject value,int max)throws Exception{JSONArray n=new JSONArray();n.put(value);for(int i=0;i<a.length()&&n.length()<max;i++)n.put(a.get(i));while(a.length()>0)a.remove(a.length()-1);for(int i=0;i<n.length();i++)a.put(n.get(i));}
    private static String join(JSONArray a){StringBuilder b=new StringBuilder();for(int i=0;i<a.length();i++){if(i>0)b.append(',');b.append(a.optString(i));}return b.length()==0?"none":b.toString();}
    private static String truncate(String s,int n){if(s==null)return"";return s.length()<=n?s:s.substring(0,n);}
    private static String fmt(double d){return String.format(Locale.US,"%.1f",d);}
    private static double clampDouble(double v,double min,double max){return Math.max(min,Math.min(max,v));}
    private static final class Signal{final String id;final double confidence,score;Signal(String i,double c,double s){id=i;confidence=c;score=s;}boolean hasAny(){return confidence>0&&score>0;}double weighted(){return confidence*score;}}
}
